using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Reflection;
namespace LoopPedal {
sealed class PerformanceScene {
 public Engine[] Banks;public PerformanceTimeline Timeline;
 public static Layer Copy(Layer l){return new Layer{AudioId=l.AudioId,Name=l.Name,Original=l.Original,Audio=l.Audio,Stretch=l.Stretch,Pitch=l.Pitch,Cutoff=l.Cutoff,Gain=l.Gain,DubDecay=l.DubDecay,Pan=l.Pan,TrimStart=l.TrimStart,TrimLength=l.TrimLength,Mute=l.Mute,Solo=l.Solo,Reverse=l.Reverse,LiveMode=l.LiveMode,PreserveFormants=l.PreserveFormants,Offset=l.Offset};}
 public static void Settings(Engine from,Engine to){to.BPM=from.BPM;to.BeatsPerBar=from.BeatsPerBar;to.BeatUnit=from.BeatUnit;to.Bars=from.Bars;to.CountInBars=from.CountInBars;to.ClickDuringRecord=from.ClickDuringRecord;to.SingleLooper=from.SingleLooper;to.Destructive=from.Destructive;to.AutoOverdub=from.AutoOverdub;to.WaitForInput=from.WaitForInput;to.TriggerDb=from.TriggerDb;to.StartQuantize=from.StartQuantize;to.InputMode=from.InputMode;to.Sync=from.Sync;to.WarpLayers=from.WarpLayers;to.WarpFrames=from.WarpFrames;to.LoopFrames=from.LoopFrames;to.LoopOrigin=from.LoopOrigin;to.Frame=from.Frame;to.Playing=from.Playing;to.DubFeedback=from.DubFeedback;from.Fx.CopySharedSettingsTo(to.Fx);to.Fx.Reverb=from.Fx.Reverb;to.Fx.Delay=from.Fx.Delay;to.Fx.Grain=from.Fx.Grain;to.Fx.Filter=from.Fx.Filter;to.Fx.Freeze=from.Fx.Freeze;}
 public static PerformanceScene Capture(Engine[] banks){lock(banks[0].Gate)lock(banks[1].Gate){var result=new PerformanceScene{Banks=new[]{new Engine(),new Engine()},Timeline=banks[0].Performance==null?new PerformanceTimeline():banks[0].Performance.copy()};for(int i=0;i<2;i++){Settings(banks[i],result.Banks[i]);result.Banks[i].Layers=banks[i].Layers.Select(Copy).ToList();}return result;}}
 public PerformanceScene Prepare(){var ready=Capture(Banks);ready.Timeline=Timeline.copy();var port=new PerformanceControl(ready.Banks);for(int b=0;b<2;b++)foreach(var l in ready.Banks[b].Layers){if(l.Pitch!=0||l.Stretch!=1||ready.Banks[b].WarpLayers)port.Prepare(1000+b*8,l.AudioId);}for(int i=0;i<ready.Timeline.count;i++)port.Prepare(ready.Timeline.lanes[i].target,ready.Timeline.lanes[i].audio);foreach(var m in ready.Timeline.mods)if(m.enabled)for(int i=0;i<m.destinations();i++)port.Prepare(m.targetAt(i),m.audioAt(i));return ready;}
 public void Apply(Engine[] target,bool retire=true){for(int i=0;i<2;i++){var b=target[i];if(retire)foreach(var l in b.Layers)if(l.Stream!=null)b.RetireStream(l.Stream);Settings(Banks[i],b);b.Layers=Banks[i].Layers;b.Frame=b.LoopOrigin;b.PlaybackPending=false;}target[0].Performance=Timeline;}
 static readonly FieldInfo[] FxFields=typeof(MasterFx).GetFields(BindingFlags.Public|BindingFlags.Instance).Where(f=>f.FieldType==typeof(float)||f.FieldType==typeof(int)||f.FieldType==typeof(bool)).OrderBy(f=>f.Name).ToArray();
 public void Write(BinaryWriter d,bool audio){d.Write(Banks[0].SingleLooper);for(int b=0;b<2;b++){var e=Banks[b];d.Write(e.BPM);d.Write(e.BeatsPerBar);d.Write(e.BeatUnit);d.Write(e.Bars);d.Write(e.CountInBars);d.Write(e.ClickDuringRecord);d.Write(e.Destructive);d.Write(e.AutoOverdub);d.Write(e.WaitForInput);d.Write(e.TriggerDb);d.Write(e.StartQuantize);d.Write(e.InputMode);d.Write(e.Sync);d.Write(e.WarpLayers);d.Write(e.WarpFrames);d.Write(e.LoopFrames);d.Write(e.LoopOrigin);d.Write(e.DubFeedback);d.Write(audio&&e.Playing);d.Write(FxFields.Length);foreach(var f in FxFields){d.Write(f.Name);if(f.FieldType==typeof(float))d.Write((float)f.GetValue(e.Fx));else if(f.FieldType==typeof(int))d.Write((int)f.GetValue(e.Fx));else d.Write((bool)f.GetValue(e.Fx));}d.Write(e.Layers.Count);foreach(var l in e.Layers){d.Write(l.AudioId);d.Write(l.Name??"Loop");d.Write(l.Offset);d.Write(l.Stretch);d.Write(l.Pitch);d.Write(l.Cutoff);d.Write(l.Gain);d.Write(l.DubDecay);d.Write(l.Pan);d.Write(l.TrimStart);d.Write(l.TrimLength);d.Write(l.Mute);d.Write(l.Solo);d.Write(l.Reverse);d.Write(l.LiveMode);d.Write(l.PreserveFormants);if(audio){d.Write(l.Original.Length);foreach(float v in l.Original)d.Write(v);}}}Timeline.write(d);}
 public static PerformanceScene Read(BinaryReader d){var s=new PerformanceScene{Banks=new[]{new Engine(),new Engine()}};bool single=d.ReadBoolean();foreach(var e in s.Banks){e.SingleLooper=single;e.BPM=d.ReadDouble();e.BeatsPerBar=d.ReadInt32();e.BeatUnit=d.ReadInt32();e.Bars=d.ReadInt32();e.CountInBars=d.ReadInt32();e.ClickDuringRecord=d.ReadBoolean();e.Destructive=d.ReadBoolean();e.AutoOverdub=d.ReadBoolean();e.WaitForInput=d.ReadBoolean();e.TriggerDb=d.ReadDouble();e.StartQuantize=d.ReadInt32();e.InputMode=d.ReadInt32();e.Sync=d.ReadBoolean();e.WarpLayers=d.ReadBoolean();e.WarpFrames=d.ReadInt32();e.LoopFrames=d.ReadInt32();e.LoopOrigin=d.ReadInt64();e.DubFeedback=d.ReadDouble();e.Playing=d.ReadBoolean();if(!PerformanceTimeline.finite(e.BPM)||e.BPM<20||e.BPM>300||e.BeatsPerBar<2||e.BeatsPerBar>7||e.BeatUnit!=4&&e.BeatUnit!=8||e.Bars<1||e.Bars>64||e.CountInBars<0||e.CountInBars>2||!PerformanceTimeline.finite(e.DubFeedback)||e.DubFeedback<0||e.DubFeedback>1)throw new IOException("Invalid project timing");int fields=d.ReadInt32();if(fields<1||fields>FxFields.Length)throw new IOException("Unsupported FX format");for(int field=0;field<fields;field++){string name=d.ReadString();var f=Array.Find(FxFields,item=>item.Name==name);if(f==null)throw new IOException("Invalid FX parameter");if(f.FieldType==typeof(float)){float v=d.ReadSingle();if(float.IsNaN(v)||float.IsInfinity(v))throw new IOException("Invalid FX value");f.SetValue(e.Fx,v);}else if(f.FieldType==typeof(int))f.SetValue(e.Fx,d.ReadInt32());else f.SetValue(e.Fx,d.ReadBoolean());}int count=d.ReadInt32();if(count<0||count>64)throw new IOException("Invalid layer count");for(int i=0;i<count;i++){var l=new Layer();l.AudioId=d.ReadInt64();l.Name=d.ReadString();l.Offset=d.ReadInt64();l.Stretch=d.ReadDouble();l.Pitch=d.ReadDouble();l.Cutoff=d.ReadDouble();l.Gain=d.ReadDouble();l.DubDecay=d.ReadDouble();l.Pan=d.ReadDouble();l.TrimStart=d.ReadDouble();l.TrimLength=d.ReadDouble();l.Mute=d.ReadBoolean();l.Solo=d.ReadBoolean();l.Reverse=d.ReadBoolean();l.LiveMode=d.ReadBoolean();l.PreserveFormants=d.ReadBoolean();int n=d.ReadInt32();if(n<2||n>48000*600*2||n%2!=0||!PerformanceTimeline.finite(l.Stretch)||l.Stretch<.5||l.Stretch>2||!PerformanceTimeline.finite(l.Pitch)||Math.Abs(l.Pitch)>12||!PerformanceTimeline.finite(l.Cutoff)||l.Cutoff<40||l.Cutoff>20000||!PerformanceTimeline.finite(l.DubDecay)||l.DubDecay<0||l.DubDecay>1||!PerformanceTimeline.finite(l.Gain)||l.Gain<0||l.Gain>1.5||!PerformanceTimeline.finite(l.Pan)||Math.Abs(l.Pan)>1||!PerformanceTimeline.finite(l.TrimStart)||!PerformanceTimeline.finite(l.TrimLength)||l.TrimStart<0||l.TrimLength<=0||l.TrimLength>10000)throw new IOException("Invalid layer");l.Original=new float[n];for(int j=0;j<n;j++){float v=d.ReadSingle();if(float.IsNaN(v)||float.IsInfinity(v))throw new IOException("Invalid audio");l.Original[j]=v;}l.Audio=DSP.Region(l.Original,l.TrimStart,l.TrimLength);e.Layers.Add(l);}}s.Timeline=PerformanceTimeline.read(d);return s;}
}
sealed class PerformanceScenes {
 public readonly PerformanceScene[] Slots=new PerformanceScene[8];public readonly string[] Names={"Scene 1","Scene 2","Scene 3","Scene 4","Scene 5","Scene 6","Scene 7","Scene 8"};public PerformanceScene Pending;public long At;public int Queued=-1,Active=-1;public bool Changed;public int Fade;float lastL,lastR,fromL,fromR,correctionL,correctionR;public Engine[] Retiring;public LoopProvider RetiringProvider;readonly byte[] oldBytes=new byte[1920];readonly float[] oldSamples=new float[480];
 public void Tick(Engine[] banks){if(Pending==null||banks[0].AudioFrame<At)return;lock(banks[1].Gate){if(Retiring!=null){for(int i=0;i<2;i++){Retiring[i].Layers=banks[i].Layers;Retiring[i].Frame=banks[i].Frame;Retiring[i].Playing=banks[i].Playing;}}Pending.Apply(banks,Retiring==null);Pending=null;Active=Queued;Queued=-1;Changed=true;Fade=960;fromL=lastL;fromR=lastR;}}
 public void Blend(float[] samples,int frames){if(Fade>0&&RetiringProvider!=null){RetiringProvider.Read(oldBytes,0,frames*8);Buffer.BlockCopy(oldBytes,0,oldSamples,0,frames*8);if(Fade==960){correctionL=fromL-oldSamples[0];correctionR=fromR-oldSamples[1];}}for(int i=0;i<frames;i++){if(Fade>0){float t=1-Fade/960f,t2=t*t*(3-2*t);float oldL=RetiringProvider==null?fromL:oldSamples[i*2]+correctionL*(float)Math.Exp(-t*16);float oldR=RetiringProvider==null?fromR:oldSamples[i*2+1]+correctionR*(float)Math.Exp(-t*16);samples[i*2]=oldL*(1-t2)+samples[i*2]*t2;samples[i*2+1]=oldR*(1-t2)+samples[i*2+1]*t2;Fade--;}lastL=samples[i*2];lastR=samples[i*2+1];}if(Fade==0&&Retiring!=null){foreach(var bank in Retiring)foreach(var layer in bank.Layers)if(layer.Stream!=null)RetireOwner.RetireStream(layer.Stream);Retiring=null;RetiringProvider=null;}}
 public Engine RetireOwner;

 public void Write(BinaryWriter d){for(int i=0;i<8;i++){d.Write(Names[i]);var slot=Slots[i];d.Write(slot!=null);if(slot!=null)slot.Write(d,true);}}
 public static PerformanceScenes Read(BinaryReader d){var s=new PerformanceScenes();for(int i=0;i<8;i++){s.Names[i]=d.ReadString();if(d.ReadBoolean())s.Slots[i]=PerformanceScene.Read(d);}return s;}
}
sealed partial class Engine {public PerformanceScenes Scenes=new PerformanceScenes();}
}
